package br.com.admeclesial.domain.financeiro;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDate; import java.util.UUID;
@Entity @Table(name="alocacao_pagamento",schema="adm_eclesial") public class AlocacaoPagamento { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(nullable=false,unique=true,updatable=false) UUID uuid; @Column(name="pagamento_id",nullable=false) Long pagamentoId; @Column(name="parcela_a_pagar_id",nullable=false) Long parcelaAPagarId; @Column(nullable=false,precision=15,scale=2) BigDecimal valor; @PrePersist void pre(){if(uuid==null)uuid=UUID.randomUUID();} public Long getId(){return id;} public UUID getUuid(){return uuid;} public Long getPagamentoId(){return pagamentoId;} public Long getParcelaAPagarId(){return parcelaAPagarId;} public BigDecimal getValor(){return valor;} public void setPagamentoId(Long v){pagamentoId=v;} public void setParcelaAPagarId(Long v){parcelaAPagarId=v;} public void setValor(BigDecimal v){valor=v;} }